VOCAB = {"star": 1, "##ship": 2, "light": 3, "##sail": 4, "sail": 5}
def sig_wordpiece(word):
    if word in VOCAB: return [word]
    out, i, first = [], 0, True
    while i < len(word):
        found = None
        for j in range(len(word), i, -1):
            piece = word[i:j] if first else "##" + word[i:j]
            if piece in VOCAB:
                found = piece; break
        if found is None: return ["[SIG-UNK]"]
        out.append(found); i += len(found.lstrip("#")); first = False
    return out
for w in ["starship", "lightsail", "star"]:
    print(w, "->", sig_wordpiece(w))

PIECES = {"star": -0.5, "ship": -0.7, "starship": -0.4, "light": -0.6,
          "sail": -0.8, "lightsail": -0.5, "s": -4.0, "t": -4.0}
def best_seg(word):
    n = len(word)
    dp = [(-1e18, None)] * (n + 1)
    dp[0] = (0.0, [])
    for i in range(n):
        if dp[i][0] == -1e18: continue
        for j in range(i + 1, n + 1):
            p = word[i:j]
            if p in PIECES and dp[i][0] + PIECES[p] > dp[j][0]:
                dp[j] = (dp[i][0] + PIECES[p], dp[i][1] + [p])
    return dp[n]
for w in ["starship", "lightsail"]:
    score, seg = best_seg(w)
    print(w, "->", seg, "log-prob:", round(score, 2) if seg else "none")

