def sig_count(text):
    words = text.split()
    pieces = 0
    for w in words:
        pieces += 1 if len(w) <= 6 else 2
    return pieces, len(words)
for s in ["star ship light sail", chr(10).join(["id,name,score", "1,ada,98", "2,grace,97"])]:
    p, w = sig_count(s)
    print(repr(s[:30]), "words:", w, "pieces:", p, "pieces/word:", round(p / w, 2))

